// Documents: brochure, indicative plans per type and the price list (PDFs
// generated by the site, see app/content/documents.ts), plus each type plan.
import type { Route } from './+types/documents';
import { notFound } from '@realadvisor/sites-kit-react/server/seo';
import { Layout } from '../components/Layout';
import { Hero } from '../components/Hero';
import { EnquiryBlock } from '../components/EnquiryBlock';
import { TYPE_NAMES } from '../components/TypeStrip';
import { sites } from '../lib/data.server';
import { documentsFor, formatBytes } from '../content/documents';
import { programmeUrl, typeMix } from '../lib/fr';
import { ogImage } from '../lib/seo';
import './documents.css';

export async function loader({ params }: Route.LoaderArgs) {
  const d = await sites.development(params.slug);
  if (!d) throw notFound();
  return { d };
}

const fmtDate = (iso: string) => new Intl.DateTimeFormat('fr-FR', { day: 'numeric', month: 'long', year: 'numeric' }).format(new Date(iso));

export default function Documents({ loaderData: { d } }: Route.ComponentProps) {
  const photo = d.photos[d.photos.length - 1] ?? d.photos[0];
  const docs = documentsFor(d.slug);
  const mix = typeMix(d);
  return (
    <Layout
      title={`Documents · ${d.title} | Arvel Promotion`}
      description={`Brochure, plans et grille des prix de ${d.title} à télécharger.`}
      image={ogImage(photo?.url)}
      programme={d}
      section="documents"
      current="programmes"
      hero={<Hero size="band" photo={photo?.url} alt={photo?.alt ?? d.title} kicker={d.title} title="Documents à télécharger" />}
    >
      <section className="section section--tight" aria-labelledby="h-docs">
        <div className="wrap">
          <h2 id="h-docs" className="sr-only">Documents de {d.title}</h2>
          {docs.length > 0 ? (
            <ul className="dc-docs">
              {docs.map((doc) => (
                <li key={doc.href} className="reveal">
                  <a href={doc.href} download>
                    <span className="dc-kind">{doc.kind === 'brochure' ? 'Brochure' : doc.kind === 'plans' ? 'Plans' : 'Prix'}</span>
                    <span className="dc-t">{doc.title}</span>
                    <span className="dc-desc muted">{doc.description}</span>
                    <span className="dc-meta num">PDF · {doc.pages} p. · {formatBytes(doc.bytes)} · mis à jour le {fmtDate(doc.date)}</span>
                    <span className="dc-dl" aria-hidden="true">Télécharger ↓</span>
                  </a>
                </li>
              ))}
            </ul>
          ) : (
            <p className="muted">Les documents de ce programme sont envoyés sur demande. <a href="#contact">Demander la brochure</a></p>
          )}
        </div>
      </section>

      {mix.length > 0 && (
        <section className="section section--tight section--deep" aria-labelledby="h-plans">
          <div className="wrap">
            <div className="dc-phead">
              <h2 id="h-plans" className="h3">Plans types</h2>
              <p className="muted">Plans indicatifs et non contractuels, un par typologie. Le plan de chaque logement est sur sa page, depuis <a href={programmeUrl(d, 'logements')}>le plan de la résidence</a>.</p>
            </div>
            <ul className="dc-plans">
              {mix.map((t) => (
                <li key={t.code}>
                  <a href={`/plans/t${Math.min(5, t.rooms)}.svg`} download={`plan-${d.slug}-${t.code.toLowerCase()}.svg`}>
                    <img src={`/plans/t${Math.min(5, t.rooms)}.svg`} alt={`Plan indicatif ${t.code}`} width="400" height="340" loading="lazy" decoding="async" />
                    <span className="dc-pc"><b>{t.code}</b> {TYPE_NAMES[t.rooms]}<span className="muted num"> · {t.minSurface === t.maxSurface ? `${t.minSurface} m²` : `${t.minSurface} à ${t.maxSurface} m²`}</span></span>
                  </a>
                </li>
              ))}
            </ul>
          </div>
        </section>
      )}

      <EnquiryBlock programme={d} title="Recevoir la brochure par e-mail" />
    </Layout>
  );
}
